<template>
  <el-dialog :model-value="modelValue" title="搭配与适用" width="min(1080px,96vw)" top="4vh" :close-on-click-modal="false" :before-close="close" data-template-sales-workspace destroy-on-close>
    <div class="workspace-context"><strong>{{modelName}}</strong><el-select :model-value="version||'$draft'" aria-label="搭配与适用版本" @change="changeVersion"><el-option value="$draft" label="当前模型草稿"/><el-option v-for="item in versions" :key="item.id" :value="item.id" :label="`${item.versionName||'v'+item.version} · ${item.status==='published'?'已发布':'已下线'}`"/></el-select><span>{{nodeId?'当前选定范围':'全部规格'}} · {{combinations.length}} 合法组合 · {{scopeSkus.length}} 现有销售 SKU</span></div>
    <details class="context-trace"><summary>范围与来源详情</summary><p>模板 {{modelId}} · {{version||'模型草稿'}}<template v-if="nodeId"> · 节点 {{nodeId}}</template><el-button link @click="copyContext">复制</el-button></p><p v-if="nodeId">{{nodeLabel}}</p></details>
    <el-alert v-if="notice" :title="notice" type="warning" :closable="false"/>
    <el-alert v-for="issue in context.issues" :key="issue.message" :title="issue.message" type="warning" :closable="false"/>
    <el-tabs v-model="tab" class="workspace-tabs">
      <el-tab-pane v-if="store.can('product:sales-config:read')" label="销售搭配" name="sales">
        <template v-if="!editing">
          <SalesScopePicker v-if="attributeStart" :key="scopeInputEpoch" :model-value="selectedSelector" @update:model-value="changeScope" :model-id="modelId" :version-id="version" :initial-node-id="nodeId" @validity-change="scopeValid=$event"/>
          <section class="effective-results" data-template-sales-results>
            <article v-for="group in groups" :key="group.key" class="result-row" :data-sales-result-state="group.resolution.state"><div><el-tag :type="['conflict','invalid'].includes(group.resolution.state)?'danger':group.resolution.state==='matched'?'success':'info'">{{group.origin}}</el-tag><strong>{{group.resolution.plan?.name||stateLabel(group.resolution.state)}}</strong><span>{{group.identities.length}} 条规格</span><p v-if="group.resolution.message" class="muted">{{group.resolution.message}}</p><ul v-if="group.resolution.plan" class="plan-summary"><li v-for="item in group.resolution.plan.items.filter(item=>item.enabled)" :key="item.id">{{item.name}}：{{item.required?'必选':'可选'}}，最多 {{item.maxKinds}} 款</li></ul></div><el-button v-if="canEdit && nodeId && groups.length>1" @click="startEdit(group)">设置这 {{group.identities.length}} 条规格</el-button></article>
            <el-empty v-if="!groups.length" :description="attributeStart?'请先明确选择属性值或完整规格':'此范围没有可证明的合法组合'" :image-size="55"/>
          </section>
          <div class="workspace-actions"><el-button v-if="canEdit" type="primary" :disabled="!combinations.length||!scopeValid||!!nodeId&&groups.length>1" data-template-configure-sales @click="startEdit()">{{nodeId?'为此范围单独设置':'设置模板默认'}}</el-button><el-button v-if="canEdit && draftWorkCopy && version" :disabled="!mappingValid" data-template-apply-draft-version @click="preparePublishedDraft">核对并应用到此发布版本</el-button><el-button v-if="canEdit && hasWorkingCopy" data-template-resume-sales @click="startEdit()">继续工作草稿</el-button><el-button link @click="router.push('/sales-configurations')">全局选配方案</el-button></div>
          <p v-if="!version" class="muted">当前查看模型草稿。正式应用时，选择已发布版本并核对实际范围。</p>
          <details v-if="scopeBindings.length" class="context-trace"><summary>查看当前版本的范围设置（{{scopeBindings.length}}）</summary><article v-for="binding in scopeBindings" :key="binding.id" class="binding-row"><span>{{binding.name}} · {{binding.enabled?'已启用':'未启用'}} · revision {{binding.revision}}</span><el-button link @click="editBinding(binding)">{{canEdit?'编辑工作草稿':'查看设置'}}</el-button><el-button v-if="canEdit&&binding.enabled&&binding.mode!=='default'&&store.can('product:sales-config:publish')" link type="danger" @click="restoreDefault(binding)">停用单独设置，恢复默认</el-button></article></details>
        </template>
        <SalesBindingDialog v-else ref="bindingEditor" :model-value="editing" :binding-id="bindingId" :model-id="modelId" :node-id="nodeId" :version-id="version" :readonly="readonly" :initial-draft="initialDraft" embedded contextual @update:model-value="editing=$event" @saved="editing=false"/>
      </el-tab-pane>
      <el-tab-pane label="适用关系" name="compatibility">
        <TemplateCompatibilityDialog ref="compatibilityEditor" :model-value="modelValue" :model-id="modelId" :initial-node-id="nodeId" :scope-selector="selectedSelector" :version-id="version||undefined" :readonly="readonly" embedded @update:model-value="value=>{if(!value)close()}"/>
      </el-tab-pane>
      <el-tab-pane v-if="store.can('product:sales-config:read')" label="试选预览" name="preview">
        <el-select v-model="previewSkuId" filterable clearable aria-label="试选实际销售 SKU" placeholder="选择此范围已有的实际销售 SKU"><el-option v-for="sku in scopeSkus" :key="sku.id" :value="sku.id" :label="`${savedSkuName(sku)} · ${savedSkuCode(sku)}`"/></el-select>
        <p v-if="!scopeSkus.length" class="muted">此版本范围暂时没有可准确对应的销售 SKU。合法规格数量不代表已建商品数量。</p>
        <template v-if="previewSkuId"><div class="workspace-actions"><el-button type="primary" @click="openShopping(previewSkuId)">到销售选购查看</el-button><span class="muted">仅查看，不加入本次清单</span></div><el-alert v-if="trial?.resolution.message" :title="trial.resolution.message" type="info" :closable="false"/><article v-for="row in trial?.rows||[]" :key="row.key" class="candidate-row"><div><strong>{{row.summary?.name||row.item.name}}</strong><span>{{candidateState(row)}}</span><details><summary>依据与来源</summary><p>{{row.reason}}</p><p>{{row.item.name}} · {{row.plan?'方案 v'+row.plan.version:'商品关联'}}</p></details></div><el-button v-if="row.skuId" @click="openShopping(row.skuId)">查看商品</el-button></article><el-empty v-if="!trial?.rows.length" description="当前没有可展示的选配项目；可查看来源或维护当前范围" :image-size="55"/></template>
      </el-tab-pane>
    </el-tabs>
    <div class="workspace-footer"><el-button @click="close()">关闭</el-button></div>
  </el-dialog>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useRouter} from 'vue-router'
import {useCatalogStore,uid} from '../../stores/catalog'
import {salesBindingContext,resolveSalesSource,resolveSalesPlanForCombination,previewSalesBinding,salesSignature} from '../../domain/salesConfiguration'
import {selectorForNode,selectorForCombination,templateSelectorCoverage} from '../../domain/templateCompatibility'
import {savedSkuName,savedSkuCode} from '../../domain/productList'
import {isRealSku} from '../../domain/catalogIdentity'
import {newBenefitPackageDraft} from '../../domain/benefitPackages'
import {querySalesCandidates} from '../../domain/salesSelection'
import type {TemplateSpecSelector} from '../../domain/templateCompatibilityTypes'
import type {SalesCandidate,SalesOptionBinding,SalesPlanResolution} from '../../domain/salesConfigurationTypes'
import SalesBindingDialog from './SalesBindingDialog.vue'
import SalesScopePicker from './SalesScopePicker.vue'
import TemplateCompatibilityDialog from '../template-compatibility/TemplateCompatibilityDialog.vue'
const props=defineProps<{modelValue:boolean;modelId:string;nodeId?:string;versionId?:string|null;readonly?:boolean;initialTab?:string}>()
const emit=defineEmits<{'update:modelValue':[boolean]}>()
const store=useCatalogStore(),router=useRouter(),tab=ref('sales'),version=ref<string|null>(null),selectedSelector=ref<TemplateSpecSelector>(),scopeValid=ref(true),editing=ref(false),bindingId=ref(''),initialDraft=ref<SalesOptionBinding>(),notice=ref(''),previewSkuId=ref(''),workEpoch=ref(0),scopeInputEpoch=ref(0)
const bindingEditor=ref<InstanceType<typeof SalesBindingDialog>>(),compatibilityEditor=ref<InstanceType<typeof TemplateCompatibilityDialog>>()
const canEdit=computed(()=>!props.readonly&&store.can('product:sales-config:update'))
const modelName=computed(()=>store.data.specCanvases.find(item=>item.templateId===props.modelId)?.name||store.data.templates.find(item=>item.id===props.modelId)?.name||props.modelId)
const versions=computed(()=>store.data.specModelVersions.filter(item=>item.templateId===props.modelId).sort((a,b)=>b.version-a.version))
const context=computed(()=>salesBindingContext(store.data,props.modelId,version.value))
const attributeStart=computed(()=>context.value.byNode.get(props.nodeId||'')?.nodeType==='ATTRIBUTE')
const nodeLabel=computed(()=>{const node=context.value.byNode.get(props.nodeId||'');return node?`${store.data.params.find(item=>item.id===node.attributeId)?.name||node.attributeId||''} ${node.valueId||''}`:'节点不属于当前版本'})
function resetRange(){scopeValid.value=true;notice.value='';selectedSelector.value=undefined;if(props.nodeId){const node=context.value.byNode.get(props.nodeId);if(node?.nodeType==='VALUE'){const result=selectorForNode(context.value,props.nodeId);selectedSelector.value=result.selector;notice.value=result.message}else if(!node)notice.value='来源节点不属于当前版本，无法证明范围映射，请重新选择实际范围。'}previewSkuId.value=''}
watch(()=>[props.modelValue,props.modelId,props.nodeId,props.versionId],()=>{if(!props.modelValue)return;version.value=props.versionId||null;tab.value=store.can('product:sales-config:read')?(props.initialTab||'sales'):'compatibility';editing.value=false;resetRange()},{immediate:true})
const combinations=computed(()=>{if(!props.nodeId)return context.value.combinations;if(!selectedSelector.value)return [];const coverage=templateSelectorCoverage(context.value,selectedSelector.value);return context.value.combinations.filter(combo=>coverage.identities.has(combo.identityKey))})
const scopeSkus=computed(()=>{const ids=new Set(combinations.value.map(combo=>combo.identityKey));return store.data.skus.filter(sku=>{if(!isRealSku(store.data,sku))return false;const source=resolveSalesSource(store.data,sku.id);return source.state==='resolved'&&source.modelId===props.modelId&&source.versionId===version.value&&ids.has(source.identityKey)})})
const scopeBindings=computed(()=>(store.data.salesOptionBindings||[]).filter(binding=>binding.schemaVersion===1&&binding.scope.kind==='model'&&binding.scope.modelId===props.modelId&&binding.scope.versionId===version.value&&(!props.nodeId||binding.mode==='default'||!!binding.scope.selector&&[...templateSelectorCoverage(context.value,binding.scope.selector).identities].some(id=>combinations.value.some(combo=>combo.identityKey===id)))))
type ResultGroup={key:string;resolution:SalesPlanResolution;origin:string;identities:string[]}
const groups=computed(()=>{const map=new Map<string,ResultGroup>();for(const combo of combinations.value){const resolution=resolveSalesPlanForCombination(store.data,{modelId:props.modelId,versionId:version.value,identityKey:combo.identityKey},context.value);const own=resolution.bindingIds.some(id=>scopeBindings.value.find(item=>item.id===id)?.mode!=='default'),origin=resolution.state==='conflict'?'存在冲突':resolution.state==='invalid'?'引用失效':resolution.state==='unconfigured'?'未配置':own?'此范围单独设置':'沿用模板默认';const key=salesSignature([resolution.state,resolution.plan?.planId,resolution.plan?.version,origin]);const existing=map.get(key);if(existing)existing.identities.push(combo.identityKey);else map.set(key,{key,resolution,origin,identities:[combo.identityKey]})}return [...map.values()]})
const workingKey=computed(()=>bindingId.value||`new:${props.modelId}:${version.value||'draft'}:${props.nodeId||'default'}`)
watch(editing,value=>{if(!value)workEpoch.value++})
const hasWorkingCopy=computed(()=>{workEpoch.value;return !!store.getSalesBindingWorkingCopy(workingKey.value).copy})
const draftWorkCopy=computed(()=>{workEpoch.value;return store.getSalesBindingWorkingCopy(`new:${props.modelId}:draft:${props.nodeId||'default'}`).copy})
const mappingValid=computed(()=>{const draft=draftWorkCopy.value?.draft;if(!draft||draft.scope.kind!=='model'||!version.value||context.value.issues.length)return false;if(draft.scope.nodeId&&!context.value.byNode.has(draft.scope.nodeId))return false;return draft.mode==='default'||!!draft.scope.selector&&!templateSelectorCoverage(context.value,draft.scope.selector).message&&templateSelectorCoverage(context.value,draft.scope.selector).identities.size>0})
function stateLabel(state:string){return ({none:'此范围不展示选配',unconfigured:'尚未配置选配方案',conflict:'不同完整结果重叠',invalid:'引用失效'} as Record<string,string>)[state]||state}
async function startEdit(group?:ResultGroup){if(!canEdit.value)return;if(group){if(!await canLeave())return;acceptContextChange();}notice.value='';const chosen=group||(groups.value.length===1?groups.value[0]:undefined);let selector=selectedSelector.value;if(group){selector={anyOf:group.identities.map(id=>selectorForCombination(context.value.byIdentity.get(id)!)).flatMap(item=>item?.anyOf||[])};selectedSelector.value=selector}const exact=scopeBindings.value.filter(binding=>props.nodeId?binding.mode!=='default'&&binding.scope.kind==='model'&&salesSignature(binding.scope.selector)===salesSignature(selector):binding.mode==='default');bindingId.value=exact.length===1?exact[0]!.id:'';initialDraft.value={schemaVersion:1,id:'',revision:0,name:`${modelName.value}${props.nodeId?' · '+nodeLabel.value:'默认选配'}`,enabled:false,scope:{kind:'model',modelId:props.modelId,versionId:version.value,...(props.nodeId?{nodeId:props.nodeId,selector}: {})},mode:props.nodeId?(chosen?.resolution.state==='none'?'none':'replace'):'default',planId:chosen?.resolution.plan?.planId||null,planVersion:chosen?.resolution.plan?.version||null,source:'模板搭配与适用',updatedAt:''};if(exact.length===1)initialDraft.value=undefined;editing.value=true}
function editBinding(binding:SalesOptionBinding){bindingId.value=binding.id;initialDraft.value=undefined;editing.value=true}
function preparePublishedDraft(){if(!mappingValid.value||!draftWorkCopy.value)return;const draft=JSON.parse(JSON.stringify(draftWorkCopy.value.draft)) as SalesOptionBinding;if(draft.scope.kind!=='model')return;const selector=draft.scope.selector;const targets=scopeBindings.value.filter(binding=>binding.mode===draft.mode&&binding.scope.kind==='model'&&(draft.mode==='default'||salesSignature(binding.scope.selector)===salesSignature(selector)));if(targets.length>1){notice.value='此发布范围存在多个设置，请先处理重叠记录后再应用。';return}const target=targets[0];if(target&&store.getSalesBindingWorkingCopy(target.id).copy){notice.value='此发布范围已有独立工作草稿，请先继续核对该草稿。';return}draft.id=target?.id||'';draft.revision=target?.revision||0;draft.enabled=target?.enabled||false;draft.scope.versionId=version.value;bindingId.value=target?.id||'';initialDraft.value=draft;editing.value=true}
async function canLeave(){if(editing.value&&!await bindingEditor.value?.canDiscard())return false;return compatibilityEditor.value?await compatibilityEditor.value.canDiscard():true}
async function changeScope(selector:TemplateSpecSelector|undefined){if(!await canLeave()){scopeInputEpoch.value++;return}acceptContextChange();selectedSelector.value=selector}
function acceptContextChange(){bindingEditor.value?.acceptContextChange();compatibilityEditor.value?.acceptContextChange()}
async function close(done?:()=>void){if(!await canLeave())return;acceptContextChange();emit('update:modelValue',false);done?.()}
async function changeVersion(id:string){if(!await canLeave())return;acceptContextChange();version.value=id==='$draft'?null:id;editing.value=false;bindingId.value='';resetRange()}
async function copyContext(){try{await navigator.clipboard.writeText(JSON.stringify({modelId:props.modelId,versionId:version.value,nodeId:props.nodeId,selector:selectedSelector.value}));ElMessage.success('已复制范围与来源')}catch{notice.value='复制失败，请在详情中选择并复制 ID。'}}
async function restoreDefault(binding:SalesOptionBinding){const actor=store.activeUserId,previewActor=store.previewUserId,signature=salesSignature(binding);try{await ElMessageBox.confirm('停用此范围的单独设置后，将重新按模板默认及其他有效范围计算。','恢复默认',{confirmButtonText:'停用并恢复默认',cancelButtonText:'返回'})}catch{return}const draft={...binding,enabled:false},review=previewSalesBinding(store.data,draft);const result=await store.saveSalesOptionBinding({draft,expectedRevision:binding.revision,expectedBasis:review.stamp,requestId:uid('restore-sales-default')},()=>props.modelValue&&actor===store.activeUserId&&previewActor===store.previewUserId&&signature===salesSignature(store.data.salesOptionBindings?.find(item=>item.id===binding.id)));if(!result.ok)notice.value=result.message||'操作失败，原设置已保留'}
const trial=computed(()=>previewSkuId.value?querySalesCandidates(store.data,newBenefitPackageDraft(),previewSkuId.value):undefined)
function candidateState(row:SalesCandidate){return row.canAdd?({compatible:'已确认适用',conditional:'需核对条件',pending:'依据待确认','not-required':'独立选购',incompatible:'明确不适用'})[row.status]:'不可选 · '+(row.status==='incompatible'?'明确不适用':row.reason)}
async function openShopping(id:string){if(await canLeave()){acceptContextChange();await router.push({path:'/sales-shopping',query:{sku:id}})}}
</script>
<style scoped>
.workspace-context{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.workspace-context>.el-select{width:240px}.workspace-context>span{font-size:13px;color:var(--el-text-color-secondary)}.context-trace{margin:12px 0;color:var(--el-text-color-secondary);font-size:12px}.context-trace summary,.candidate-row summary{cursor:pointer}.context-trace p{overflow-wrap:anywhere}.workspace-tabs{margin-top:14px}.result-row,.candidate-row,.binding-row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid var(--el-border-color-lighter)}.result-row strong,.candidate-row strong{margin:0 10px}.result-row>div{min-width:0}.plan-summary{display:flex;gap:8px 20px;flex-wrap:wrap;padding-left:20px;font-size:13px}.workspace-actions,.workspace-footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:16px}.workspace-footer{justify-content:flex-end}.muted{font-size:12px;color:var(--el-text-color-secondary);line-height:1.6}.candidate-row details{font-size:12px;margin-top:8px}.candidate-row>div>span{font-size:12px;color:var(--el-text-color-secondary)}@media(max-width:650px){.workspace-context>.el-select{width:100%}.result-row,.binding-row{align-items:flex-start;flex-wrap:wrap}.plan-summary{display:block}.plan-summary li{margin:6px 0}}
</style>
